import {restoreGuided,guidedWeaknesses,guidedResultScore} from './workshop-repair-guided-history.mjs';
import {guidedReviews} from './workshop-repair-guided-review.mjs';
import {repairDay,shiftDay} from './workshop-repair-review.mjs';
import {repairWeekStart} from './workshop-repair-weekly.mjs';
function usable(rows,now){const seen=new Set();return rows.map(restoreGuided).filter(r=>{if(!r||r.phase!=='complete'||!Number.isFinite(Date.parse(r.finished))||Date.parse(r.finished)>+now||seen.has(r.id))return false;seen.add(r.id);return true;}).sort((a,b)=>Date.parse(a.finished)-Date.parse(b.finished));}
function stats(rows){const decisions=rows.flatMap(r=>r.rounds);return {count:rows.length,average:rows.length?Math.round(rows.reduce((n,r)=>n+guidedResultScore(r),0)/rows.length):null,days:new Set(rows.map(r=>repairDay(new Date(r.finished)))).size,hints:rows.reduce((n,r)=>n+r.hints,0),unnecessary:decisions.filter(r=>!r.useful).length,total:decisions.length};}
export function guidedWeekly(rows,goal=2,now=new Date()){
 const today=repairDay(now),start=repairWeekStart(today),priorStart=shiftDay(start,-7),priorEnd=shiftDay(today,-7),clean=usable(rows,now),inRange=(a,b)=>clean.filter(r=>{const d=repairDay(new Date(r.finished));return d>=a&&d<=b;}),currentRows=inRange(start,today),current=stats(currentRows),previous=stats(inRange(priorStart,priorEnd)),reviews=guidedReviews(clean,now),strengths=guidedWeaknesses(clean);
 const hardest=guidedWeaknesses(currentRows).filter(g=>g.wrong||g.hints).sort((a,b)=>b.wrong-a.wrong||b.hints-a.hints||a.key.localeCompare(b.key)).slice(0,3),planStart=shiftDay(start,7),planEnd=shiftDay(planStart,6),capacity=Math.max(1,Math.min(5,Math.floor(Number(goal)||2)));let remaining=reviews.entries;const days=[];
 for(let i=0;i<7;i++){const day=shiftDay(planStart,i),entries=remaining.filter(e=>e.due<=day).map(e=>{const g=strengths.find(g=>g.key===e.key);return {...e,wrong:g?.wrong||0,total:g?.total||0,hints:g?.hints||0};}).sort((a,b)=>b.wrong/Math.max(1,b.total)-a.wrong/Math.max(1,a.total)||b.hints-a.hints||a.due.localeCompare(b.due)||a.key.localeCompare(b.key)).slice(0,capacity);days.push({day,entries});const keys=new Set(entries.map(e=>e.key));remaining=remaining.filter(e=>!keys.has(e.key));}
 return {today,start,priorStart,priorEnd,current,previous,delta:current.average===null||previous.average===null?null:current.average-previous.average,streak:reviews.streak,hardest,plan:{start:planStart,end:planEnd,days,capacity,scheduled:days.reduce((n,d)=>n+d.entries.length,0),backlog:remaining.filter(e=>e.due<=planEnd).length}};
}
